import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // Parse colors
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE BACKGROUND (Avoid flat voids)
  // Create an engineered gradient card back to frame our content beautifully
  const backgroundGeo = new PlaneGeometry(2.4, 1.8);
  const backgroundMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
    flatShading: true
  });

  // TSL Gradient mixing surface and ink, with an accent glow at the bottom edge
  const uvY = uv().y;
  const gradientNode = mix(
    color(palette.surface),
    mix(color(palette.ink), color(palette.accent), 0.08),
    uvY
  );
  backgroundMat.colorNode = gradientNode;

  const backgroundMesh = new Mesh(backgroundGeo, backgroundMat);
  backgroundMesh.position.set(0, 0, -0.05);
  group.add(backgroundMesh);

  // 2. PRODUCT IMAGE LAYER
  const imgGeo = new PlaneGeometry(2.2, 1.3);
  const imgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 0.95
  });
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0.15, 0.01);
  group.add(imgMesh);

  const fallbackUrl = '/prism-mock/home/nodes/feature-card.png';
  const imageUrl = config.imageUrl ?? fallbackUrl;

  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    imgMat.map = texture;
    imgMat.needsUpdate = true;
  }).catch((err) => {
    console.warn('Could not load card image, using color fallback', err);
    imgMat.colorNode = color(palette.ink);
  });

  // 3. TEXT LAYER (Collection card 3 label)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textLabel = items[0]?.text ?? 'Collection 3';

  // Using display font size guidelines: display is Lora, subhead/headline sized beautifully
  const textObj = ctx.fontAtlas.createText(textLabel, {
    fontSize: 39,
    color: palette.paper,
    align: 'center'
  });

  // Position the label centered near the bottom of our card structure
  textObj.position.set(0, -0.65, 0.05);
  // Apply a subtle scale adjustment to standard MSDF text layout fits
  textObj.scale.setScalar(0.008); 
  group.add(textObj);

  // 4. LOCALIZED LIGHTING (Product-shot style hierarchy)
  const keyLight = new DirectionalLight(palette.paper, 1.1);
  keyLight.position.set(1.5, 2.5, 2.0);
  group.add(keyLight);

  const rimLight = new DirectionalLight(palette.accent, 0.8);
  rimLight.position.set(-2.0, -1.5, 1.0);
  group.add(rimLight);

  // 5. MOTION WITH WEIGHT (GSAP transition)
  group.position.y += 0.25;
  group.scale.setScalar(0.95);

  const tl = gsap.timeline({ defaults: { ease: 'power4.out' } });
  tl.to(group.position, { y: 0, duration: 0.9 }, 0);
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9 }, 0);
  timelines.push(tl);

  // 6. CLEANUP
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    backgroundGeo.dispose();
    backgroundMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
  };

  return group;
}
